// ---------------------------------------------------------------- languages: Russian (the source language of every text in the game) and English
// Texts are translated where they are drawn (T.draw / T.width / T.wrap): the exact string is looked up, and anything composed at run time
// (numbers, names, pieces glued together) is translated piece by piece (the longest known Russian pieces first). LANG_EN is generated by tools/i18n/merge.py.
const I18N = (() => {
  const CY = /[А-Яа-яЁё]/;
  let lang = 'ru', map = null, core = null, re = null, cache = new Map();
  const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  function build() {
    map = new Map();
    for (const [k, v] of Object.entries(LANG_EN)) { map.set(k, v); if (k.length <= 40 && k !== k.toUpperCase()) map.set(k.toUpperCase(), v.toUpperCase()); }   // texts the code writes in capitals
    if (typeof SPECIES !== 'undefined') for (const s of SPECIES) if (s.ru && s.en && CY.test(s.ru)) { map.set(s.ru, s.en); if (s.ru.length <= 40) map.set(s.ru.toUpperCase(), s.en.toUpperCase()); }
    // the code lower-cases / capitalises names on the fly ('Малая коробка' -> 'малая коробка'): the same pieces with the first letter changed
    const lc = x => x.charAt(0).toLowerCase() + x.slice(1), uc = x => x.charAt(0).toUpperCase() + x.slice(1);
    for (const [k, v] of [...map]) { if (k.length > 60) continue; if (/^[А-ЯЁ][а-яё]/.test(k) && /^[A-Z][a-z]/.test(v) && !map.has(lc(k))) map.set(lc(k), lc(v)); else if (/^[а-яё]/.test(k) && /^[a-z]/.test(v) && !map.has(uc(k))) map.set(uc(k), uc(v)); }
    // long texts are cut into sentences by the code ('Где искать' shows the first sentences of a description)
    for (const [k, v] of [...map]) if (k.length > 40 && /[.!?] /.test(k)) { const a = k.split(/(?<=[.!?])\s+/), b = v.split(/(?<=[.!?])\s+/); if (a.length === b.length && a.length > 1) a.forEach((x, i) => { if (!map.has(x) && CY.test(x)) map.set(x, b[i]); }); }
    // the code also takes the first comma-separated part of a habitat text (the 'look' hint)
    for (const [k, v] of [...map]) if (k.length > 12 && k.includes(',')) { const a = k.split(','), b = v.split(','); if (a.length === b.length) a.forEach((x, i) => { x = x.trim(); if (x && !map.has(x) && CY.test(x)) map.set(x, b[i].trim()); }); }
    // lines of multi-line texts are drawn one by one
    for (const [k, v] of [...map]) if (k.includes('\n')) { const a = k.split('\n'), b = v.split('\n'); if (a.length === b.length) a.forEach((x, i) => { if (!map.has(x) && CY.test(x)) map.set(x, b[i]); }); }
    // pieces are matched without their edge spaces (the spaces stay in the text), so ' с' cannot steal the space before 'с.ш.'
    core = new Map(); for (const strong of [true, false]) for (const [k, v] of map) { const c = k.trim(); if (c && (k === c) === strong && (strong || !core.has(c))) core.set(c, v.trim()); }
    const keys = [...core.keys()].sort((a, b) => b.length - a.length);
    const L = '[А-Яа-яЁёA-Za-z]';   // a piece that starts/ends with a letter must not start/end inside a longer word
    re = new RegExp(keys.map(k => (/^[А-Яа-яЁё]/.test(k) ? '(?<!' + L + ')' : '') + esc(k) + (/[А-Яа-яЁё]$/.test(k) ? '(?!' + L + ')' : '')).join('|'), 'g');
  }
  function tr(s) {
    if (lang === 'ru' || typeof s !== 'string' || !CY.test(s)) return s;
    let r = cache.get(s); if (r !== undefined) return r;
    if (!map) build();
    r = map.get(s); if (r === undefined) r = s.replace(re, m => core.get(m));
    if (cache.size > 8000) cache.clear(); cache.set(s, r); return r;
  }
  // the language is saved in the settings; the first start follows the system language
  function guess() { const q = /[#&?]lang=(ru|en)/.exec(location.hash + location.search); if (q) return q[1]; if (/debug/.test(location.hash)) return 'ru';   // the tests (#debug) keep running in Russian unless #lang=en is given
    const n = (navigator.language || 'en').toLowerCase(); return /^(ru|uk|be|kk)/.test(n) ? 'ru' : 'en'; }
  function sync() {
    const s = typeof Save !== 'undefined' && Save.data && Save.data.settings; let l = s && s.lang;
    if (l !== 'ru' && l !== 'en') { l = guess(); if (s) s.lang = l; }
    if (l !== lang) { lang = l; cache.clear(); }
    try { document.documentElement.lang = lang; document.title = 'Flora0world: Butterflies'; } catch (e) {}
  }
  function set(l) { if (l !== 'ru' && l !== 'en') return; const s = Save.data.settings; s.lang = l; Save.write(); lang = l; cache.clear(); sync(); }
  // the first n characters of a line being typed out (n counts characters of the Russian line)
  const typed = (line, n) => lang === 'ru' ? line.slice(0, Math.floor(n)) : (() => { const f = tr(line); return f.slice(0, Math.floor(n / Math.max(1, line.length) * f.length)); })();
  return { tr, typed, sync, set, toggle() { set(lang === 'ru' ? 'en' : 'ru'); }, get lang() { return lang; }, get en() { return lang === 'en'; }, name: l => l === 'ru' ? 'Русский' : 'English' };
})();
